const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define region (Lake Erie + upstate NY)
  const roi = ee.Geometry.Rectangle([-84.5, 41.0, -74.0, 44.5]);

  // 2. Function to get snow data (using MODIS NDSI)
  function getSnowData(date) {
    // Try MODIS first (daily snow cover)
    const modisCol = ee.ImageCollection('MODIS/061/MOD10A1')
      .filterBounds(roi)
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .select('NDSI_Snow_Cover');

    if (modisCol.size().getInfo() > 0) {
      return modisCol.mosaic()
        .updateMask(ee.Image(0).updateMask(0)) // Clear any existing masks
        .clip(roi);
    }

    // Fallback: Landsat 8/9 with NDSI calculation
    const landsatCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(ee.Date(date).advance(-3, 'day'), date)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    if (landsatCol.size().getInfo() > 0) {
      const landsat = landsatCol.first();
      // NDSI = (Green - SWIR) / (Green + SWIR) -> Band 3 (Green), Band 6 (SWIR)
      const ndsi = landsat.normalizedDifference(['SR_B3', 'SR_B6'])
        .rename('NDSI')
        .clip(roi);
      // Snow threshold: NDSI > 0.4
      return ndsi.updateMask(ndsi.gt(0.4));
    }

    return null;
  }

  // 3. Get images for both dates
  const date1 = '2020-02-22';
  const date2 = '2020-03-01';

  const snowImg1 = getSnowData(date1);
  const snowImg2 = getSnowData(date2);

  // 4. Check data availability
  if (!snowImg1 || !snowImg2) {
    console.log(`${date1} Data: ${snowImg1 ? 'Found' : 'None'}`);
    console.log(`${date2} Data: ${snowImg2 ? 'Found' : 'None'}`);
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate snow extent (valid pixels count)
  const stats1 = snowImg1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = snowImg2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const count1 = stats1.get(snowImg1.bandNames().get(0)).getInfo();
  const count2 = stats2.get(snowImg2.bandNames().get(0)).getInfo();

  console.log(`${date1} Snow Pixels: ${count1}`);
  console.log(`${date2} Snow Pixels: ${count2}`);

  // 6. Check for valid pixels
  if (count1 === 0 && count2 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Compare and determine answer
  if (count1 === null || count2 === null || 
      typeof count1 !== 'number' || typeof count2 !== 'number') {
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Output final answer
  if (count2 > count1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
